-- Synthetic users and temporary configuration only; all work rolls back.
begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();req uuid:=gen_random_uuid();debit uuid:=gen_random_uuid();reply jsonb;pin text:=lpad((floor(random()*10000)::integer)::text,4,'0');mid text;rid text;cat text;target text;item uuid;coupon uuid;day date:=(now() at time zone 'Asia/Seoul')::date;denied boolean;before_name text;
begin
 insert into auth.users(id,email) values(a,'release4-admin-'||a||'@example.invalid'),(b,'release4-member-'||b||'@example.invalid'),(c,'release4-coach-'||c||'@example.invalid');
 update public.gym_members set role='admin',status='approved' where id=a;
 update public.gym_members set role='member',status='approved' where id=b;
 update public.gym_members set role='coach',status='approved',coach_permissions='[]' where id=c;
 perform public.onoff_points(a,jsonb_build_object('action','settings','enabled',true,'attendancePoints',10,'recordPoints',20,'maxBalance',100,'pin',pin));
 perform public.onoff_points(a,jsonb_build_object('action','grant','memberId',b,'requestId',req,'amount',150,'reason','rollback grant'));
 perform public.onoff_points(a,jsonb_build_object('action','grant','memberId',b,'requestId',req,'amount',150,'reason','rollback grant'));
 if (select balance from public.gym_point_accounts where user_id=b)<>100 then raise exception 'grant cap/retry';end if;
 perform public.onoff_points(a,jsonb_build_object('action','deduct','memberId',b,'requestId',debit,'amount',30,'reason','rollback debit'));
 perform public.onoff_points(a,jsonb_build_object('action','deduct','memberId',b,'requestId',debit,'amount',30,'reason','rollback debit'));
 if (select balance from public.gym_point_accounts where user_id=b)<>70 or (select count(*) from public.gym_point_ledger where user_id=b)<>2 then raise exception 'debit retry: balance %, ledger %',(select balance from public.gym_point_accounts where user_id=b),(select count(*) from public.gym_point_ledger where user_id=b);end if;
 denied:=false;begin perform public.onoff_points(a,jsonb_build_object('action','grant','memberId',b,'requestId',debit,'amount',30,'reason','cross action'));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'request action changed';end if;
 denied:=false;begin perform public.onoff_points(c,jsonb_build_object('action','deduct','memberId',b,'requestId',gen_random_uuid(),'amount',1,'reason','forbidden'));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'coach debit';end if;
 perform public.onoff_points(a,jsonb_build_object('action','deduct','memberId',b,'requestId',gen_random_uuid(),'amount',1000,'reason','cap debit'));
 if (select balance from public.gym_point_accounts where user_id=b)<>0 then raise exception 'negative balance';end if;
 perform public.onoff_points(a,jsonb_build_object('action','method-save','name','Rollback method '||a,'kind','manual'));
 select id into mid from public.gym_point_methods where name='Rollback method '||a;
 perform public.onoff_points(a,jsonb_build_object('action','rule-save','name','Rollback reward '||a,'amount',7,'methodId',mid));
 select id into rid from public.gym_point_rules where name='Rollback reward '||a;
 perform public.onoff_points(a,jsonb_build_object('action','method-save','id',mid,'name','Renamed method '||a,'kind','manual'));
 perform public.onoff_points(a,jsonb_build_object('action','rule-save','id',rid,'name','Renamed reward '||a,'amount',5,'methodId',mid));
 perform public.onoff_points(a,'{"action":"method-delete","id":"attendance"}');
 perform public.onoff_points(a,jsonb_build_object('action','method-save','id',mid,'name','Custom attendance '||a,'kind','attendance'));
 if (select auto_key from public.gym_point_rules where id=rid)<>'attendance' then raise exception 'method edit did not rebind event';end if;
 insert into public.gym_attendance(user_id,date) values(b,day) on conflict do nothing;
 insert into public.gym_attendance(user_id,date) values(b,day) on conflict do nothing;
 insert into public.gym_records(id,user_id,date,program,section,body,writer_id) values(gen_random_uuid(),b,'1904-01-01','WOD','S1','{}',b),(gen_random_uuid(),b,'1904-01-01','B/T','S1','{}',b);
 if (select balance from public.gym_point_accounts where user_id=b)<>25 then raise exception 'automatic awards not once per day';end if;
 perform public.onoff_points(a,jsonb_build_object('action','method-delete','id',mid));
 if not (select deleted from public.gym_point_rules where id=rid) then raise exception 'method delete left live rule';end if;
 delete from public.gym_point_ledger where user_id=b and event_key='attendance:'||day::text;
 delete from public.gym_attendance where user_id=b;
 insert into public.gym_attendance(user_id,date) values(b,day);
 if (select balance from public.gym_point_accounts where user_id=b)<>25 then raise exception 'deleted method awarded';end if;
 perform public.onoff_points(a,'{"action":"product-save","name":"Release4 rollback gift","description":"rollback only","price":5,"uses":1}');
 select id into item from public.gym_point_products where name='Release4 rollback gift';
 reply:=public.onoff_points(b,jsonb_build_object('action','exchange','productId',item,'requestId',gen_random_uuid(),'expectedPrice',5,'expectedUses',1));coupon:=(reply->>'couponId')::uuid;
 if (select balance from public.gym_point_accounts where user_id=b)<>20 then raise exception 'exchange balance';end if;
 if not (select expires_at>now()+interval '27 days' and expires_at<now()+interval '32 days' from public.gym_point_coupons where id=coupon) then raise exception 'coupon month';end if;
 perform public.onoff_points(b,jsonb_build_object('action','use','couponId',coupon,'requestId',gen_random_uuid(),'pin',pin));
 if (select remaining from public.gym_point_coupons where id=coupon)<>0 then raise exception 'coupon consume';end if;
 denied:=false;begin perform public.onoff_points(b,jsonb_build_object('action','use','couponId',coupon,'requestId',gen_random_uuid(),'pin',pin));exception when raise_exception then denied:=true;end;if not denied then raise exception 'used coupon accepted';end if;
 denied:=false;begin perform public.onoff_rm_categories(c,'{"action":"add","label":"Forbidden category"}');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'category permission';end if;
 reply:=public.onoff_rm_categories(a,jsonb_build_object('action','add','label','Rollback category '||left(a::text,8)));cat:=reply->>'id';
 perform public.onoff_rm_categories(a,jsonb_build_object('action','edit','id',cat,'label','Renamed category '||left(a::text,8)));
 select value->0->>0 into target from public.gym_settings where key='rmCategories';
 select x->>'name' into before_name from public.gym_settings,jsonb_array_elements(value) x where key='rmCatalogue' and x->>'id'='front-squat';
 update public.gym_settings set value=(select jsonb_agg(case when x->>'id'='front-squat' then jsonb_set(x,'{category}',to_jsonb(cat)) else x end) from jsonb_array_elements(value) x) where key='rmCatalogue';
 insert into public.gym_rms(id,user_id,body) values(gen_random_uuid(),b,'{"movementId":"front-squat","lbs":135,"date":"1904-01-01"}');
 perform public.onoff_rm_categories(a,jsonb_build_object('action','delete','id',cat,'targetId',target));
 if not exists(select 1 from public.gym_settings,jsonb_array_elements(value) x where key='rmCatalogue' and x->>'id'='front-squat' and x->>'name'=before_name and x->>'category'=target) then raise exception 'category transfer lost movement';end if;
 if not exists(select 1 from public.gym_rms where user_id=b and body->>'movementId'='front-squat' and body->>'lbs'='135') then raise exception 'category change lost record';end if;
 update public.gym_members set coach_permissions='["rm"]' where id=c;
 perform public.onoff_rm_categories(c,jsonb_build_object('action','add','label','Coach category '||left(c::text,8)));
end $$;
select true as release4_sql_passed,not has_table_privilege('authenticated','public.gym_point_methods','select') as methods_private,not has_function_privilege('anon','public.onoff_rm_categories(uuid,jsonb)','execute') as categories_private;
rollback;
